// DirectFlight holds one of the objects substituting for the abstract AbstractDirectFlight.
// At most one field is set.
type DirectFlight struct {
	DirectFlightClass   *DirectFlightClass   `xml:"http://www.aixm.aero/schema/5.1.1 DirectFlightClass"`
	DirectFlightSegment *DirectFlightSegment `xml:"http://www.aixm.aero/schema/5.1.1 DirectFlightSegment"`
	NilReason           string               `xml:"nilReason,attr,omitempty"`
}

// Object returns the object that is set, or nil.
func (c *DirectFlight) Object() any {
	switch {
	case c == nil:
		return nil
	case c.DirectFlightClass != nil:
		return c.DirectFlightClass
	case c.DirectFlightSegment != nil:
		return c.DirectFlightSegment
	}
	return nil
}

// SegmentPoint holds one of the objects substituting for the abstract AbstractSegmentPoint.
// At most one field is set.
